function loadRead(){try{const v=JSON.parse(localStorage.getItem('toncode-read')||'[]');return Array.isArray(v)?[...new Set(v.filter(n=>Number.isInteger(n)&&n>=0&&n<lessons.length))]:[]}catch{return []}}
let viewed=loadRead(),view='home',lang='cpp',activeLesson=0,step=0,loopN=5;
const content=document.querySelector('#content');
function esc(v){return String(v).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
function wrap(code,l=lang){if(l==='py'||code.startsWith('#include'))return code;return l==='cpp'?'#include <iostream>\nusing namespace std;\n\nint main() {\n'+code.split('\n').map(s=>'    '+s).join('\n')+'\n    return 0;\n}':'#include <stdio.h>\n\nint main(void) {\n'+code.split('\n').map(s=>'    '+s).join('\n')+'\n    return 0;\n}'}
function lessonRows(){return lessons.map((l,i)=>`<button class="lesson" data-lesson="${i}"><span class="lesson-num">${viewed.includes(i)?'✓':String(i+1).padStart(2,'0')}</span><span class="lesson-info"><h3>${l.title}</h3><p>${l.sub} &nbsp; · &nbsp; ${l.time} นาที &nbsp; · &nbsp; ${tasks.filter(t=>t[1]===i).length} โจทย์</p></span><span class="level">${l.tag}</span><span class="arrow">↗</span></button>`).join('')}
function intro(k,t,d){return `<div class="intro"><div><span class="eyebrow">${k}</span><h1>${t}</h1><p>${d}</p></div></div>`}
