syntaxGuides.py.push([{"title": "โครงสร้าง def และ return", "syntax": "def square(value):\n    return value * value", "parts": [["def", "เริ่มนิยามฟังก์ชัน"], ["square", "ชื่อที่ใช้เรียก"], ["value", "พารามิเตอร์รับข้อมูล ไม่ต้องระบุชนิดในแบบพื้นฐานนี้"], [": และการเยื้อง", "เริ่มบล็อกคำสั่งของฟังก์ชัน"], ["return", "ส่งค่ากลับและจบการเรียกครั้งนั้น"]], "flow": "นิยามฟังก์ชันไว้ → เรียกด้วยค่า → ทำงานในบล็อก → ส่งค่ากลับ", "pitfall": "ต้องให้บรรทัด def ทำงานก่อนถึงบรรทัดเรียก; การนิยามยังไม่ใช่การเรียกทำงานในบล็อก"}, {"title": "เรียกใช้และส่งอาร์กิวเมนต์", "syntax": "def add(a, b):\n    return a + b\n\nanswer = add(3, 5)\nprint(answer)", "parts": [["a, b", "พารามิเตอร์ภายในฟังก์ชัน"], ["3, 5", "อาร์กิวเมนต์ที่ส่งให้ a และ b ตามลำดับ"], ["add(3, 5)", "เรียกแล้วมีค่าของนิพจน์เป็นผลที่คืนกลับมา"], ["answer", "รับค่า 8 เพื่อใช้ต่อหรือแสดงผล"]], "flow": "ประเมินอาร์กิวเมนต์ → ส่งให้ฟังก์ชัน → รอ return → เก็บผล → print", "pitfall": "ใส่วงเล็บเมื่อเรียกใช้ และส่งจำนวนอาร์กิวเมนต์ให้ตรงกับที่นิยามในแบบฝึกหัดนี้"}, {"title": "ตัวแปรเฉพาะที่และการเรียกซ้ำ", "syntax": "def increase(value):\n    result = value + 1\n    return result\n\nx = 10\ny = increase(x)", "parts": [["value และ result", "ชื่อเฉพาะที่ภายในฟังก์ชัน"], ["x", "ตัวแปรด้านนอกยังเป็น 10 ในตัวอย่างที่ใช้จำนวนเต็มนี้"], ["y", "รับค่าที่คืนมาเป็น 11"], ["แต่ละการเรียก", "เริ่มทำคำสั่งในฟังก์ชันใหม่ ไม่สะสมค่าท้องถิ่นจากครั้งก่อนโดยอัตโนมัติ"]], "flow": "อ่านค่า x → ผูกค่ากับ value → สร้าง result → คืนค่าให้ y", "pitfall": "ตัวแปรภายในไม่ได้ใช้จากภายนอกได้โดยตรง และการกำหนดชื่อพารามิเตอร์ใหม่ในตัวอย่างจำนวนเต็มนี้ไม่เปลี่ยนชื่อ x ด้านนอก"}, {"title": "return ต่างจาก print และ None", "syntax": "def show_message():\n    print(\"Ready\")\n\nresult = show_message()\n# แสดง Ready แต่ result เป็น None", "parts": [["print", "ส่งข้อความออกหน้าจอ ไม่ใช่การส่งคำตอบให้ผู้เรียก"], ["return ค่า", "ส่งค่าจากฟังก์ชันให้ผู้เรียก"], ["ไม่มี return หรือ return เปล่า", "Python คืน None"], ["None", "หมายถึงไม่มีค่าผลลัพธ์ที่ระบุ ไม่ใช่จำนวน 0"]], "flow": "เรียก show_message → แสดงข้อความ → จบฟังก์ชัน → คืน None ให้ result", "pitfall": "อย่าเขียน print(f()) เมื่อ f แสดงผลอยู่แล้วและไม่คืนค่า เว้นแต่ตั้งใจจะแสดง None เพิ่ม"}]);
function renderSyntaxGuide(){return `<section class="panel syntax-guide"><span class="eyebrow">01 / รู้จักโครงสร้างคำสั่งก่อน</span><h2>อ่านโครงสร้าง แล้วค่อยเขียนโปรแกรม</h2><p class="muted">เลือกภาษาเพื่ออ่านแม่แบบ ความหมายของแต่ละส่วน และลำดับการทำงาน คำไทยในแม่แบบเป็นคำอธิบาย ให้แทนด้วยคำสั่งหรือเงื่อนไขจริงก่อนนำไปรัน</p>${languageTabs()}<div class="syntax-grid">${syntaxGuides[lang][activeLesson].map((g,i)=>`<article class="syntax-topic"><span class="eyebrow">${String(activeLesson+1).padStart(2,'0')}.${i+1}</span><h3>${g.title}</h3><pre class="editor syntax-code">${esc(g.syntax)}</pre><dl class="syntax-parts">${g.parts.map(([part,meaning])=>`<div><dt><code>${esc(part)}</code></dt><dd>${esc(meaning)}</dd></div>`).join('')}</dl><div class="syntax-flow"><b>ลำดับการทำงาน</b><p>${esc(g.flow)}</p></div><div class="syntax-pitfall"><b>ระวังตรงนี้</b><p>${esc(g.pitfall)}</p></div></article>`).join('')}</div><p class="note">อ่านครบแล้ว เลื่อนลงดูตัวอย่างโปรแกรมและลองคิด ก่อนเลือกโจทย์ฝึกเขียนบน eLabSheet</p></section>`}
function renderLesson(){const l=lessons[activeLesson];content.innerHTML=intro(`LESSON ${String(activeLesson+1).padStart(2,'0')} / ${String(lessons.length).padStart(2,'0')}`,l.title,`${l.time} นาที · ${lang==='py'?pythonSubs[activeLesson]:l.sub}`)+renderSyntaxGuide()+`<div class="lesson-layout"><section class="panel"><span class="eyebrow">02 / ทบทวนแนวคิด</span><h2>${l.title}</h2><p>${lang==='py'?pythonLessons[activeLesson].body:l.body}</p><div class="notice">💡 ${lang==='py'?pythonLessons[activeLesson].key:l.key}</div><h3>ลองคิดก่อนดูคำตอบ</h3><p>${['ถ้าต้องการแสดงสองบรรทัด จะบอกให้โปรแกรมขึ้นบรรทัดใหม่อย่างไร?','ถ้าป้อน 18 โปรแกรมตัวอย่างจะแสดงอะไร?','ถ้า a = 7 และ b = 2 ผลรวมจะเป็นเท่าไร?','ถ้า n = 0 โปรแกรมจะเข้า if หรือ else?','ถ้า n = 3 คำสั่งในลูปจะทำงานกี่รอบ?','ถ้าข้อมูลตัวแรกเป็น 0 จะมีตัวเลขถูกแสดงหรือไม่?','ถ้า square(x) คืน x*x แล้ว square(4) คืนค่าอะไร?'][activeLesson]}</p><details><summary>ดูคำตอบและเหตุผล</summary>${[lang==='py'?'ใช้ print() สองครั้ง หรือใส่ \\n ในข้อความ':'ใช้ \\n หรือ endl เพื่อขึ้นบรรทัดใหม่','แสดง 18 เพราะรับค่าเก็บใน age แล้วแสดงค่าเดิม','ได้ 9 เพราะตัวอย่างใช้ a + b','เข้า if เพราะ 0 % 2 เท่ากับ 0 จึงแสดง EVEN','3 รอบ โดย i มีค่า 1, 2 และ 3','ไม่มี เพราะเงื่อนไข n != 0 เป็นเท็จตั้งแต่ก่อนเข้าลูป','คืน 16 ให้ผู้เรียก เพราะ 4*4 เท่ากับ 16 ส่วนการแสดงผลเป็นหน้าที่ของ print, printf หรือ cout ที่นำค่านั้นไปใช้'][activeLesson]}</details><button class="btn" id="markRead">${viewed.includes(activeLesson)?'✓ บันทึกว่าอ่านแล้ว':'อ่านเข้าใจแล้ว ✓'}</button></section><section class="panel"><span class="eyebrow">03 / ดูตัวอย่างโปรแกรม</span><div class="tabs"><button class="tab ${lang==='cpp'?'selected':''}" data-lang="cpp">C++17</button><button class="tab ${lang==='c'?'selected':''}" data-lang="c">C11</button><button class="tab ${lang==='py'?'selected':''}" data-lang="py">Python 3</button></div><pre class="editor">${esc(wrap(l[lang]))}</pre><p class="muted">${activeLesson===0?'ไม่ต้องรับข้อมูล · ผลลัพธ์: Hello, TOI0!':'ลองคัดลอกไปทดลองด้วยเครื่องมือรันภาษาที่เลือก แล้วเปลี่ยนค่าข้อมูลนำเข้า'}</p><button class="btn secondary" id="copyCode">คัดลอกโค้ด</button>${activeLesson>=4?' <button class="text-btn" data-view="lab">ดูการทำงานของ for →</button>':''}</section></div><div class="section-title"><h2>04 / ลงมือฝึกเขียน</h2><span class="muted">${tasks.filter(t=>t[1]===activeLesson).length} โจทย์ประจำบท</span></div><div class="problem-grid">${tasks.map((t,i)=>t[1]===activeLesson?taskCard(t,i):'').join('')}</div><div class="section-title"><button class="text-btn" data-lesson="${Math.max(0,activeLesson-1)}">← บทก่อนหน้า</button>${activeLesson<lessons.length-1?`<button class="btn" data-lesson="${activeLesson+1}">บทถัดไป →</button>`:'<button class="btn" data-view="problems">ฝึกโจทย์ทั้งหมด →</button>'}</div>`}
function taskCard(t,i){return `<article class="problem-card"><span class="problem-code">TC-${String(i+1).padStart(2,'0')} &nbsp; / &nbsp; บท ${t[1]+1}${i>=60?' &nbsp; · ฟังก์ชัน':''}</span><h3>${t[0]}</h3><small class="skill-label">${taskSkills[i]}</small><p>${t[2]}</p><button class="text-btn" data-task="${i}">อ่านโจทย์และไปเขียนโค้ด ↗</button></article>`}
function filterTasks(){const q=document.querySelector('#search').value.trim().toLowerCase(),f=document.querySelector('#filter').value,group=document.querySelector('#collection').value;let count=0;document.querySelector('#problemGrid').innerHTML=tasks.map((t,i)=>{if(('TC-'+String(i+1).padStart(2,'0')+' '+t[0]+' '+taskSkills[i]).toLowerCase().includes(q)&&(f==='all'||String(t[1])===f)&&(group==='all'||group==='functions'&&i>=60||group==='basic'&&i<60)){count++;return taskCard(t,i)}return ''}).join('')||'<p class="empty">ไม่พบโจทย์ ลองเปลี่ยนคำค้นหรือเลือกทุกบทเรียน</p>';document.querySelector('#resultCount').textContent=`พบ ${count} ข้อ จากทั้งหมด ${tasks.length} ข้อ`}
let activeTask=0,practiceMode='fill',practiceLang='cpp';
function practiceLinks(i){const links=(practiceMode==='fill'?window.TONCODE_FILL_PRACTICE:window.TONCODE_PRACTICE)?.[i]||{};return `<div class="practice-links">${[['cpp','C++'],['c','C'],['py','Python']].map(([l,label])=>links[l]?`<a class="btn ${l==='c'?'secondary':''}" href="${esc(links[l])}" target="_blank" rel="noopener noreferrer">${practiceMode==='fill'?'เติมโค้ด':'เขียนเต็ม'} ${label} บน eLabSheet ↗</a>`:`<span class="muted">กำลังเตรียม ${label}</span>`).join('')}</div>`}
function openTask(i){activeTask=i;renderTask();const dialog=document.querySelector('#modal');if(!dialog.open)dialog.showModal()}
function renderTask(){const i=activeTask,t=tasks[i],meta=window.TONCODE_FILL_META?.[i]?.[practiceLang];document.querySelector('#modalBody').innerHTML=`<span class="problem-code">TC-${String(i+1).padStart(2,'0')} · ${lessons[t[1]].title}</span><h1>${t[0]}</h1><span class="pill">${taskSkills[i]}</span><p>${t[2]}</p><h3>ข้อมูลนำเข้าและขอบเขต</h3><p>${t[5]}</p><h3>ตัวอย่าง</h3><div class="io"><div><small>INPUT</small><pre>${esc(t[3])}</pre></div><div><small>OUTPUT</small><pre>${esc(t[4])}</pre></div></div><div class="practice-box"><h3>เลือกวิธีฝึก</h3><div class="tabs practice-modes"><button class="tab ${practiceMode==='fill'?'selected':''}" data-practice-mode="fill">เติมโค้ดในช่องว่าง</button><button class="tab ${practiceMode==='full'?'selected':''}" data-practice-mode="full">เขียนโปรแกรมเต็ม</button></div>${practiceMode==='fill'?`<p>โครงสร้างโปรแกรมมีให้แล้ว เติมเฉพาะส่วนที่ขาดบน eLabSheet เลือกภาษาด้านล่างเพื่อดูแม่แบบก่อนเริ่ม</p><div class="tabs">${[['cpp','C++'],['c','C'],['py','Python']].map(([key,label])=>`<button class="tab ${practiceLang===key?'selected':''}" data-practice-lang="${key}">${label}</button>`).join('')}</div>${meta?`<div class="blank-count">มี ${meta.count} ช่องให้เติม</div><pre class="editor fill-preview">${esc(meta.preview)}</pre><ol class="fill-hints">${meta.hints.map((hint,k)=>`<li><b>ช่อง ${k+1}:</b> ${esc(hint)}</li>`).join('')}</ol>`:''}`:'<p>เริ่มจากช่องโค้ดว่าง เขียนโปรแกรมฉบับเต็ม รับข้อมูลและแสดงผลตามโจทย์ แล้วส่งตรวจบน eLabSheet</p>'}${practiceLinks(i)}<p class="note">เปิดในแท็บใหม่ ระบบ eLabSheet จะรันโปรแกรมเพื่อตรวจผลลัพธ์ กลับมาอ่านบทเรียนต่อได้เมื่อฝึกเสร็จ</p></div><details><summary>ขอคำใบ้แนวคิด</summary><p>${t[6]}</p></details>`}
function languageTabs(){return `<div class="tabs">${[['cpp','C++17'],['c','C11'],['py','Python 3']].map(([key,label])=>`<button class="tab ${lang===key?'selected':''}" data-lang="${key}">${label}</button>`).join('')}</div>`}
function loopCode(n){if(lang==='py')return `for i in range(1, ${n+1}):\n    print(i)`;if(lang==='c')return `for (int i = 1; i <= ${n}; i++) {\n    printf("%d\\n", i);\n}`;return `for (int i = 1; i <= ${n}; i++) {\n    cout << i << "\\n";\n}`}
function renderLab(){content.innerHTML=intro('THE LITTLE LAB','เห็นลูปทำงาน ทีละรอบ','เปลี่ยน n แล้วก้าวไปทีละคำสั่ง สังเกตค่าตัวนับ เงื่อนไข และผลลัพธ์')+`<div class="lesson-layout"><section class="panel"><span class="eyebrow">01 / ตั้งจำนวนรอบ</span><div class="lab-controls"><label for="loopN">n =</label><input class="field" id="loopN" type="number" min="1" max="12" value="${loopN}"><span class="muted">กำหนดได้ 1–12</span></div>${languageTabs()}<pre class="editor">${esc(loopCode(loopN))}</pre><div class="problem-actions"><button class="btn" id="nextStep">รอบถัดไป →</button><button class="btn secondary" id="resetLoop">↺ เริ่มใหม่</button></div><div id="loopStatus" role="status"></div><div class="notice">ตัวจำลองนี้แสดง for loop ตัวอย่างที่กำหนดไว้ ไม่ได้รันโค้ดที่ผู้เรียนเขียน</div></section><section class="panel"><span class="eyebrow">02 / ติดตามการทำงาน</span><h2>จากเงื่อนไข สู่ผลลัพธ์</h2><div class="loop-stage" id="loopCells"></div><h3>หน้าจอแสดงผล</h3><div class="terminal" id="loopOutput"></div><p class="muted" id="loopExplain"></p></section></div>`;updateLoop()}
function updateLoop(){document.querySelector('#loopCells').innerHTML=Array.from({length:loopN},(_,i)=>`<div class="loop-cell ${i<step?'done':''} ${i===step-1?'current':''}">${i+1}</div>`).join('');document.querySelector('#loopOutput').textContent=step?Array.from({length:Math.min(step,loopN)},(_,i)=>i+1).join('\n'):'ยังไม่มีผลลัพธ์';document.querySelector('#loopStatus').innerHTML=`<div class="feedback">${lang==='py'?(step===0?`เตรียมค่าใน range(1, ${loopN+1})`:step<=loopN?`รอบที่ ${step}: รับ i = ${step} จาก range แล้วแสดง ${step}`:'ไม่มีค่าถัดไปใน range → จบลูป'):step===0?'เตรียมเริ่ม: กำหนด i = 1':step<=loopN?`รอบที่ ${step}: i = ${step} → ${step} <= ${loopN} เป็นจริง → แสดง ${step}`:`ตรวจอีกครั้ง: i = ${loopN+1} → ${loopN+1} <= ${loopN} เป็นเท็จ → จบลูป`}</div>`;document.querySelector('#loopExplain').textContent=lang==='py'?(step>loopN?`จบแล้ว! range(1, ${loopN+1}) ให้ค่า 1 ถึง ${loopN} รวม ${loopN} รอบ`:`Python รับค่า i ถัดไปจาก range(1, ${loopN+1}) โดยไม่รวมค่าปลายทาง`):step>loopN?`จบแล้ว! ทำงานทั้งหมด ${loopN} รอบ แม้จะตรวจเงื่อนไข ${loopN+1} ครั้ง`:'หลังแสดงค่าแต่ละรอบ i++ จะเพิ่ม i ทีละ 1 ก่อนกลับไปตรวจเงื่อนไขอีกครั้ง';document.querySelector('#nextStep').disabled=step>loopN;document.querySelector('#nextStep').style.opacity=step>loopN?'.5':'1'}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){render(b.dataset.view);window.scrollTo(0,0)}if(b.dataset.lesson!==undefined){activeLesson=Number(b.dataset.lesson);render('lesson');window.scrollTo(0,0)}if(b.dataset.task!==undefined)openTask(Number(b.dataset.task));if(b.dataset.practiceMode){practiceMode=b.dataset.practiceMode;renderTask()}if(b.dataset.practiceLang){practiceLang=b.dataset.practiceLang;renderTask()}if(b.dataset.lang){lang=b.dataset.lang;if(view==='lab')renderLab();else renderLesson()}if(b.id==='closeModal')document.querySelector('#modal').close();if(b.id==='markRead'){if(!viewed.includes(activeLesson))viewed.push(activeLesson);try{localStorage.setItem('toncode-read',JSON.stringify(viewed))}catch{};renderLesson()}if(b.id==='copyCode'){try{await navigator.clipboard.writeText(wrap(lessons[activeLesson][lang]));b.textContent='คัดลอกแล้ว ✓'}catch{b.textContent='เลือกโค้ดด้านบนเพื่อคัดลอก'}}if(b.id==='nextStep'){step=Math.min(step+1,loopN+1);updateLoop()}if(b.id==='resetLoop'){step=0;updateLoop()}});
document.addEventListener('input',e=>{if(e.target.id==='search')filterTasks();if(e.target.id==='loopN'){const n=Number(e.target.value);if(Number.isInteger(n)&&n>=1&&n<=12){loopN=n;step=0;document.querySelector('.editor').textContent=loopCode(n);updateLoop()}else{document.querySelector('#loopStatus').innerHTML='<div class="feedback bad">กรุณาใส่จำนวนเต็ม 1–12</div>';document.querySelector('#nextStep').disabled=true}}});document.addEventListener('change',e=>{if(e.target.id==='filter'||e.target.id==='collection')filterTasks()});document.querySelector('#modal').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});render();
